\begin{theorem}
\label{theorem-final-bootstrap}
In Situation \ref{situation-bootstrap} for $i \leq s$ the inverse system
$\{H^i_T(M/I^nM)\}_{n \geq 0}$ is essentially constant with value $H^i_T(M)$.
In particular, $\{H^i_T(M/I^nM)\}_{n \geq 0}$ is Mittag-Leffler,
$H^i_T(M)$ is annihilated by a power of $I$, and
$H^i_T(M) = \lim H^i_T(M/I^nM)$.
\end{theorem}

